// A seeded teaching model, not a reimplementation or validation of the research system.
export const defaults={policy:'closed-loop',family:'delay',limit:.08,rps:100,background:0,target:.99,share:.5,reserveSeconds:.1,screen:false,seed:51};
export const policyNames={'closed-loop':'Adaptive controller',static:'Fixed intensity',threshold:'Threshold stop','open-loop':'Preplanned intensity'};
export const policyHints={'closed-loop':'Looks at the budget, then turns the fault up or down.',static:'Keeps the same fault intensity. The emergency guard still applies.',threshold:'Keeps intensity fixed, then stops if either SLO burns at 2× or faster.','open-loop':'Chooses intensity once using an illustrative cost, without adapting.'};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function wilson(bad,n){if(n<=0)return[0,1];const z=1.96,p=bad/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,r=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return[Math.max(0,c-r),Math.min(1,c+r)];}
export function excess(tb,tn,cb,cn){return{signed:tb-tn*cb/cn,upper:tn*Math.max(0,wilson(tb,tn)[1]-wilson(cb,cn)[0])};}
function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
export class Lab{
constructor(config={}){this.config={...defaults,...config};this.time=0;this.running=false;this.status='READY';this.reason='';this.intensity=0;this.exposure=0;this.events=[];this.history=[];this.last=null;this.lastChange=0;this.reservedRps=this.config.rps;this.expected=this.reservedRps*120;this.reserve=this.reservedRps*this.config.reserveSeconds;this.ledgers={availability:this.ledger(1-this.config.target),latency:this.ledger(.05)};}
ledger(q){return{q,allocation:q*this.expected*this.config.share,signed:0,charged:0,totalBad:0,trueInduced:0};}
event(message){this.events.unshift({time:this.time,message});}
admit(){if(this.status!=='READY')return this.status==='RUNNING';if(Object.values(this.ledgers).some(l=>l.allocation<=this.reserve)){this.status='REJECTED';this.reason='The allowance is too small to cover the stopping reserve.';this.event('Admission rejected: reserve does not fit.');return false;}if(this.config.background>Math.min(1-this.config.target,.05)){this.status='REJECTED';this.reason='The baseline is already worse than the SLO. Start healthy before adding a fault.';this.event('Admission rejected: unhealthy baseline.');return false;}this.status='RUNNING';this.intensity=this.config.policy==='closed-loop'?Math.min(.005,this.config.limit):this.config.policy==='open-loop'?Math.min(this.config.limit,...Object.values(this.ledgers).map(l=>l.allocation/this.expected)):this.config.limit;this.event('Admitted. Allocation frozen; '+this.reserve.toFixed(1)+' requests reserved for stopping.');return true;}
stop(reason){this.status='STOPPED';this.running=false;this.intensity=0;this.reason=reason;this.event(reason);}
step(){if(!this.admit())return false;const cfg=this.config;this.time++;this.intensity=Math.min(this.intensity,cfg.limit);if(['static','threshold'].includes(cfg.policy))this.intensity=cfg.limit;const applied=this.intensity;const counts={};for(const [index,cohort] of ['control','treatment'].entries()){const random=rng(cfg.seed+this.time*7919+index*104729);let a=0,l=0,ta=0,tl=0;for(let i=0;i<cfg.rps;i++){const organic=random()<cfg.background;const hit=random()<applied&&cohort==='treatment';const faultA=cfg.family==='abort'&&hit;const faultL=hit;const badA=organic||faultA;const badL=organic||faultL;a+=Number(badA);l+=Number(badL);ta+=Number(!organic&&faultA);tl+=Number(!organic&&faultL);}counts[cohort]={total:cfg.rps,availability:a,latency:l,trueAvailability:ta,trueLatency:tl};}
const burns={};const estimates={};for(const [name,ledger] of Object.entries(this.ledgers)){const c=counts.control,t=counts.treatment,e=excess(t[name],t.total,c[name],c.total);estimates[name]=e;ledger.signed+=e.signed;ledger.charged+=cfg.screen?e.upper:Math.max(0,e.signed);ledger.totalBad+=t[name];ledger.trueInduced+=t[name==='availability'?'trueAvailability':'trueLatency'];burns[name]=t[name]/t.total/ledger.q;}
this.exposure+=applied;this.last={counts,burns,estimates,applied};this.history.push({time:this.time,a:clamp(100*(1-this.ledgers.availability.charged/this.ledgers.availability.allocation),0,100),l:clamp(100*(1-this.ledgers.latency.charged/this.ledgers.latency.allocation),0,100),intensity:applied*100});
for(const [name,l] of Object.entries(this.ledgers)){if(l.totalBad+this.reserve>=l.q*this.expected){this.stop('Total service budget guard: '+name+'.');return true;}if(burns[name]>=20){this.stop('Emergency stop: severe '+name+' burn.');return true;}if(l.charged+this.reserve>=l.allocation){this.stop('Allocation guard: preserving the '+name+' stopping reserve.');return true;}}
if(cfg.rps>this.reservedRps){this.stop('Traffic exceeds the admitted reserve assumption. Reset to admit this higher load.');return true;}
if(this.time>=60){this.stop('60-second experiment complete. Fault removed in this teaching model.');return true;}
if(cfg.policy==='threshold'&&Math.max(...Object.values(burns))>=2){this.stop('Threshold policy: an SLO reached 2× burn.');return true;}
if(cfg.policy==='closed-loop'&&this.time-this.lastChange>=2){const risk=Math.max(...Object.values(this.ledgers).map(l=>(l.charged/this.time)*Math.max(1,60-this.time)/Math.max(.00001,l.allocation-l.charged-this.reserve)));const recent=this.history.slice(-5); // Burn windows in the Python controller are simplified here to the current tick.
const previous=this.intensity;if(risk>1||Math.max(...Object.values(burns))>2)this.intensity*=.5;else if(risk<.5&&Math.max(...Object.values(burns))<1)this.intensity=Math.min(cfg.limit,this.intensity+.005);if(Math.abs(previous-this.intensity)>.000001){this.lastChange=this.time;this.event(this.intensity<previous?'Turned the fault down: budget pressure or high burn.':'Turned the fault up: budget headroom and low burn.');}}
return true;}
}
export function compare(config){return Object.keys(policyNames).map(policy=>{const lab=new Lab({...config,policy});for(let i=0;i<60;i++)if(!lab.step())break;return lab;});}

